export const serviceAddonGroups = sqliteTable(
  "service_addon_groups",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    serviceId: text()
      .notNull()
      .references(() => services.id, { onDelete: "cascade" }),
    groupId: text()
      .notNull()
      .references(() => addonGroups.id, { onDelete: "cascade" }),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [
    primaryKey({ columns: [table.serviceId, table.groupId] }),
    index("service_addon_groups_group_idx").on(table.groupId),
  ]
)

export const bookingAddons = sqliteTable(
  "booking_addons",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    bookingId: text()
      .notNull()
      .references(() => bookings.id, { onDelete: "cascade" }),
    optionId: text().references(() => addonOptions.id, {
      onDelete: "set null",
    }),
    name: text().notNull(),
    priceMinor: integer(),
    durationMinutes: integer().notNull(),
    position: integer().notNull().default(0),
    ...timestamps(),
  },
  (table) => [index("booking_addons_booking_idx").on(table.bookingId)]
)

// From now on bookings.durationMinutes and bookings.priceMinor are the
// TOTALS (service + add-ons; priceMinor null only when the service has no
// price and no add-on has one). The add-ons are in booking_addons.
export const bookings = sqliteTable(
  "bookings",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    serviceId: text().references(() => services.id, { onDelete: "set null" }),
    teamMemberId: text().references(() => teamMembers.id, {
      onDelete: "set null",
    }),
    serviceName: text().notNull(),
    teamMemberName: text(),
    durationMinutes: integer().notNull(),
    priceMinor: integer(),
    currency: text().notNull(),
    startAt: text().notNull(),
    endAt: text().notNull(),
    customerName: text().notNull(),
    customerPhone: text(),
    // customerKey(customerPhone, customerName) from lib/customer-key.ts,
    // set on every new booking. Null only on bookings made before it
    // existed, until `npm run customers:backfill` fills them.
    customerKey: text(),
    source: text().notNull().default("online"),
    note: text(),
    status: text().notNull().default("confirmed"),
    ...timestamps(),
  },
  (table) => [
    index("bookings_business_idx").on(table.businessId, table.startAt),
    index("bookings_customer_idx").on(
      table.businessId,
      table.customerKey,
      table.startAt
    ),
  ]
)

// a service with NO rows here is done by everyone on the team; a service with rows is done only by those members.
export const teamMemberServices = sqliteTable(
  "team_member_services",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    teamMemberId: text()
      .notNull()
      .references(() => teamMembers.id, { onDelete: "cascade" }),
    serviceId: text()
      .notNull()
      .references(() => services.id, { onDelete: "cascade" }),
    ...timestamps(),
  },
  (table) => [
    primaryKey({ columns: [table.teamMemberId, table.serviceId] }),
    index("team_member_services_business_idx").on(table.businessId),
    index("team_member_services_service_idx").on(table.serviceId),
  ]
)

export const translations = sqliteTable(
  "translations",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    entityId: text().notNull(),
    field: text().notNull(),
    language: text().notNull(),
    sourceText: text().notNull(),
    text: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    uniqueIndex("translations_entity_field_language_idx").on(
      table.entityId,
      table.field,
      table.language
    ),
    index("translations_business_idx").on(table.businessId, table.language),
  ]
)

// One row per write the assistant runs (direct or confirmed), including
// failures. The summary is server-built, never model words.
export const assistantActions = sqliteTable(
  "assistant_actions",
  {
    id: id(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    ownerId: text().references(() => user.id, { onDelete: "set null" }),
    tool: text().notNull(),
    summary: text().notNull(),
    status: text().notNull(),
    ...timestamps(),
  },
  (table) => [index("assistant_actions_business_idx").on(table.businessId)]
)

// One saved owner-assistant chat per row. The id is a UUID made by the
// browser; messages is JSON of AssistantMessage[]. The title is the
// first owner message, set once on create and never changed after.
export const assistantConversations = sqliteTable(
  "assistant_conversations",
  {
    id: text().primaryKey(),
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    ownerId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text().notNull(),
    messages: text().notNull(),
    ...timestamps(),
  },
  (table) => [
    index("assistant_conversations_owner_idx").on(
      table.businessId,
      table.ownerId,
      table.updatedAt
    ),
  ]
)

// A business's "Connect with Koblip Chat" connection, one per business
// (docs/koblip-chat-integration.md, step 1). Both tokens are encrypted with
// lib/secret-box and never leave the server. When Chat refuses a refresh the
// tokens are dropped and needsReconnect asks the owner to connect again.
export const chatConnections = sqliteTable("chat_connections", {
  businessId: text()
    .primaryKey()
    .references(() => businesses.id, { onDelete: "cascade" }),
  workspaceId: text().notNull(),
  workspaceName: text().notNull(),
  scopes: text().notNull(),
  accessToken: text(),
  refreshToken: text(),
  accessExpiresAt: text(),
  needsReconnect: integer({ mode: "boolean" }).notNull().default(false),
  // The WhatsApp account and number Book's messages use, Chat's own ids
  // (step 2); empty until the workspace has an active number.
  wabaId: text(),
  phoneNumberId: text(),
  ...timestamps(),
})

// Book's booking templates in the business's Koblip Chat, one per message and
// language (docs/koblip-chat-integration.md, step 2): Chat's template id and
// Meta's review status, as Chat last reported it.
export const chatTemplates = sqliteTable(
  "chat_templates",
  {
    businessId: text()
      .notNull()
      .references(() => businesses.id, { onDelete: "cascade" }),
    message: text({
      enum: ["confirmed", "reminder", "changed", "cancelled", "ownerNewBooking"],
    }).notNull(),
    language: text({ enum: ["en", "es"] }).notNull(),
    chatTemplateId: text().notNull(),
    status: text().notNull(),
    ...timestamps(),
  },
  (table) => [primaryKey({ columns: [table.businessId, table.message, table.language] })]
)
